#include <atomic>
#include <functional>
#include <memory>
#include <string>
#include <system_error>
#include <utility>

using Bytes = std::string;

void async_get(std::string url,
               std::function<void(std::error_code, Bytes)> done);

// Defect in the by-reference version: `[&url, &on_done]` stores views of
// locals that die when start_download returns. The event loop invokes the
// callback on a LATER TURN, long after this frame is gone, so both reads are
// use-after-scope -- and silently so, because the closure itself is valid.

class Download : public std::enable_shared_from_this<Download> {
public:
    using Handler = std::function<void(std::error_code, Bytes)>;

    static std::shared_ptr<Download> start(std::string url, Handler done) {
        auto self = std::shared_ptr<Download>(
            new Download{std::move(done)});

        // The closure holds a WEAK reference. If the caller drops the last
        // handle before the reply arrives, lock() fails and the callback
        // does nothing instead of writing through a dead owner.
        std::weak_ptr<Download> watcher = self;
        async_get(std::move(url),
                  [watcher](std::error_code error, Bytes body) noexcept {
                      if (auto alive = watcher.lock()) {
                          alive->finish(error, std::move(body));
                      }
                  });
        return self;
    }

    void cancel() noexcept {
        finish(std::make_error_code(std::errc::operation_canceled), Bytes{});
    }

private:
    explicit Download(Handler done) : done_(std::move(done)) {}

    // Exactly one caller sees false and delivers. Cancellation after
    // completion, or a late reply after cancellation, loses the exchange and
    // returns -- so the handler runs at most once and the second party does
    // cleanup only.
    void finish(std::error_code error, Bytes body) noexcept {
        if (delivered_.exchange(true)) {
            return;
        }
        // No exception may escape an event-loop turn: there is no caller to
        // catch it, so failure is a branch, not a throw.
        try {
            done_(error, std::move(body));
        } catch (...) {
        }
    }

    Handler done_;
    std::atomic<bool> delivered_{false};
};

#include <exception>
#include <future>
#include <iostream>
#include <stdexcept>
#include <thread>
#include <utility>
#include <vector>

double portfolio_risk(const std::vector<double>& positions) {
    if (positions.empty()) {
        throw std::runtime_error{"risk input unavailable"};
    }

    double sum = 0.0;
    for (double position : positions) {
        sum += position * position;
    }
    return sum;
}

void produce_risk(std::promise<double> promise,
                  std::vector<double> positions) {
    try {
        promise.set_value(portfolio_risk(positions));
    } catch (...) {
        // Exceptions do not propagate between threads on their own; the
        // shared state is the channel. current_exception() preserves the
        // dynamic type so the consumer's catch clauses still match.
        promise.set_exception(std::current_exception());
    }
}

void consume_risk(std::vector<double> positions) {
    std::promise<double> producer;
    std::future<double> result = producer.get_future();

    std::jthread worker{produce_risk, std::move(producer),
                        std::move(positions)};

    try {
        std::cout << result.get() << '\n';
    } catch (const std::runtime_error& error) {
        std::cout << error.what() << '\n';
    }
}

#include <functional>
#include <future>
#include <memory>
#include <stdexcept>
