struct OperationCancelled : std::runtime_error {
    OperationCancelled() : std::runtime_error{"cancelled before start"} {}
};

class ThreadPool {
public:
    template<class F>
    auto submit(F&& function, std::stop_token stop)
        -> std::future<std::invoke_result_t<F&>> {
        using Result = std::invoke_result_t<F&>;

        // The task itself decides whether it runs. Throwing from inside the
        // packaged_task routes OperationCancelled into the shared state, so
        // the future becomes ready with an exception the caller can catch --
        // rather than being destroyed unfulfilled, which would surface as an
        // uninformative broken_promise.
        auto task = std::make_shared<std::packaged_task<Result()>>(
            [function = std::forward<F>(function), stop]() mutable -> Result {
                if (stop.stop_requested()) {
                    throw OperationCancelled{};
                }
                return function();
            });

        std::future<Result> result = task->get_future();

        // Invoked EXACTLY ONCE on every path, including the cancelled one.
        // Skipping the call here is the tempting shortcut that leaves the
        // caller blocked in get() until the shared state is destroyed.
        enqueue([task] { (*task)(); });
        return result;
    }

private:
    // The shared_ptr is an adaptation to the QUEUE's element type:
    // std::function requires a copyable target and packaged_task is
    // move-only. Change the queue and the worker local to
    // std::move_only_function<void()> (C++23) and the lambda can capture the
    // packaged_task directly, removing this owner and its control block.
    void enqueue(std::function<void()> work);
};

#include <chrono>
#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <stop_token>

enum class WaitResult { ready, stopped, timed_out };

class Inbox {
public:
    void deliver(int message) {
        {
            std::lock_guard lock{mutex_};
            messages_.push(message);
        }
        ready_.notify_one();
    }

    WaitResult wait_for_message(
        std::stop_token stop,
        std::chrono::steady_clock::time_point deadline,
        int& out) {
        std::unique_lock lock{mutex_};

        // The predicate is a statement about STATE. It says nothing about
        // stopping: the overload installs a stop_callback that notifies this
        // variable and re-checks, so a stop requested before this call even
        // began is observed rather than slept through.
        ready_.wait_until(lock, stop, deadline, [this] {
            return !messages_.empty();
        });

        // The status is decided HERE, from state, not from which wait won.
        // A message that arrived just before a deadline that has since
        // passed is still `ready`: the queue is the truth, and reporting
        // timed_out would drop a message that was actually delivered.
        if (!messages_.empty()) {
            out = messages_.front();
            messages_.pop();
            return WaitResult::ready;
        }
        if (stop.stop_requested()) {
            return WaitResult::stopped;
        }
        return WaitResult::timed_out;
    }

private:
    // A plain std::condition_variable has no stop-token overload. It can
    // still participate, but only through an explicit std::stop_callback
    // that calls notify_all() AND a predicate extended to
    // `!messages_.empty() || stop.stop_requested()` -- the notification only
    // wakes the waiter, and a woken waiter whose predicate ignores stopping
    // goes straight back to sleep.
    std::mutex mutex_;
    std::condition_variable_any ready_;
    std::queue<int> messages_;
};

#include <functional>
#include <mutex>
#include <stop_token>
#include <vector>

class FanOut {
public:
    explicit FanOut(std::stop_token parent)
        : parent_(std::move(parent)),
          // Registered here on purpose. If the parent was ALREADY cancelled,
          // this callback is invoked inline during construction -- which is
          // what closes the window between testing the token and installing
          // the hook. It may therefore run on this thread or on the
          // requesting thread, so it stays short.
          cancel_children_{parent_, [this] { request_all(); }} {}

    std::stop_token add_child() {
        std::lock_guard lock{mutex_};
        std::stop_source& child = children_.emplace_back();

        // Checked UNDER the same lock that request_all() takes. Without this
        // a child registered a moment after the parent was cancelled would
        // never be told: the callback has already run and cannot run again,
        // because a stop request is permanent and a second request_stop()
        // changes nothing and returns false.
        if (parent_.stop_requested()) {
            child.request_stop();
        }
        return child.get_token();
    }

    // A child that fails cancels its siblings through the same path.
    void fail() { request_all(); }

private:
    void request_all() {
        std::lock_guard lock{mutex_};
        for (std::stop_source& child : children_) {
            child.request_stop();
        }
    }

    std::stop_token parent_;
    std::mutex mutex_;
    std::vector<std::stop_source> children_;

    // Declared LAST, so it is destroyed FIRST. ~stop_callback deregisters
    // and, if the callback is running on another thread, waits for it to
    // finish -- so it can never fire into a FanOut whose mutex and vector
    // have already been destroyed.
    std::stop_callback<std::function<void()>> cancel_children_;
};

#include <coroutine>
#include <exception>
#include <functional>
#include <string>
#include <system_error>
#include <utility>

using Bytes = std::string;

struct Socket {
    void async_read(std::function<void(std::error_code, Bytes)> done);
    void cancel_read();
    bool has_buffered_data() const noexcept;
    Bytes take_buffered_data();
};

class ReadAwaiter {
public:
    explicit ReadAwaiter(Socket& socket) noexcept : socket_(socket) {}

    // Fast path: no suspension, no registration, no resume -- the whole
    // point of await_ready existing separately from await_suspend.
    bool await_ready() const noexcept {
        return socket_.has_buffered_data();
    }

    void await_suspend(std::coroutine_handle<> handle) {
        handle_ = handle;
        socket_.async_read([this](std::error_code error, Bytes body) {
            if (error) {
                failure_ = std::make_exception_ptr(
                    std::system_error{error});
            } else {
                body_ = std::move(body);
            }
            handle_.resume();
        });
        // NOTHING may follow this call that touches *this, handle_, or any
        // local of the coroutine. The callback can run on the reactor thread
        // before async_read even returns, resume the coroutine, run it to
        // completion and destroy the frame -- and this awaiter is a
        // temporary that LIVES IN THAT FRAME.
    }

    Bytes await_resume() {
        if (failure_) {
            // The failure becomes an exception in the awaiting coroutine, so
            // the caller writes try/catch instead of threading an error code
            // through every continuation.
            std::rethrow_exception(failure_);
        }
        if (body_.empty() && socket_.has_buffered_data()) {
            return socket_.take_buffered_data();  // the await_ready path
        }
        return std::move(body_);
    }

private:
    Socket& socket_;
    std::coroutine_handle<> handle_{};
    Bytes body_;
    std::exception_ptr failure_;
};

ReadAwaiter read(Socket& socket) { return ReadAwaiter{socket}; }

// The awaiter is owned by the coroutine frame, which means the registration
// outlives this function and not the other way round: before anything
// destroys a suspended frame, the pending async_read must be cancelled
// (socket.cancel_read()) or the callback must be redirected to state that
// survives independently. Otherwise the completion resumes a destroyed
// frame.

#include <atomic>
#include <coroutine>

class Event {
public:
    class Awaiter {
    public:
        explicit Awaiter(Event& event) noexcept : event_(event) {}

        // Fast path: no suspension at all if the event already fired.
        bool await_ready() const noexcept {
            return event_.set_.load();
        }

        // Returning bool lets the awaiter cancel the suspension it just
        // asked for: `false` means "do not suspend after all, resume this
        // coroutine immediately". That is what closes the window between
        // await_ready() reading false and the handle being stored -- set()
        // could have run in between, and without the re-check the coroutine
        // would park with nobody left to wake it.
        bool await_suspend(std::coroutine_handle<> handle) noexcept {
            event_.waiter_ = handle;
            if (event_.set_.load()) {
                event_.waiter_ = {};
                return false;
            }
            return true;
        }

        void await_resume() const noexcept {}

    private:
        Event& event_;
    };

    Awaiter operator co_await() noexcept { return Awaiter{*this}; }

    void set() {
        set_.store(true);
        std::coroutine_handle<> handle = waiter_;
        if (handle) {
            waiter_ = {};  // cleared first: never resume the same frame twice
            handle.resume();
        }
    }

private:
    std::atomic<bool> set_{false};
    std::coroutine_handle<> waiter_{};
};

#include <coroutine>
#include <exception>
#include <iterator>
#include <utility>

// One coroutine means one frame, so iterating the whole sequence performs a
// single allocation (or none, if the compiler elides it) and nothing per
// element -- unlike materialising every result into a container.
template<class T>
class Generator {
public:
    struct promise_type {
        T current{};
        std::exception_ptr error;

        Generator get_return_object() {
            return Generator{
                std::coroutine_handle<promise_type>::from_promise(*this)};
        }
        std::suspend_always initial_suspend() noexcept { return {}; }
        std::suspend_always final_suspend() noexcept { return {}; }

        std::suspend_always yield_value(T value) {
            current = std::move(value);   // publish, then suspend
            return {};
        }

        void return_void() noexcept {}
        void unhandled_exception() { error = std::current_exception(); }
    };

    using Handle = std::coroutine_handle<promise_type>;

    explicit Generator(Handle handle) noexcept : handle_(handle) {}
    Generator(const Generator&) = delete;
    Generator& operator=(const Generator&) = delete;
    Generator(Generator&& other) noexcept
        : handle_(std::exchange(other.handle_, {})) {}
    ~Generator() { if (handle_) handle_.destroy(); }

    class Iterator {
    public:
        explicit Iterator(Handle handle) noexcept : handle_(handle) {}

        bool operator==(std::default_sentinel_t) const noexcept {
            return !handle_ || handle_.done();
        }

        Iterator& operator++() {
            handle_.resume();
            rethrow_if_failed();
            return *this;
        }

        const T& operator*() const noexcept {
            return handle_.promise().current;
        }

    private:
        void rethrow_if_failed() const {
            if (handle_.promise().error) {
                std::rethrow_exception(handle_.promise().error);
            }
        }

        Handle handle_;
    };

    Iterator begin() {
        if (handle_) {
            handle_.resume();  // run up to the first co_yield
            if (handle_.promise().error) {
                std::rethrow_exception(handle_.promise().error);
            }
        }
        return Iterator{handle_};
    }

    std::default_sentinel_t end() const noexcept { return {}; }

private:
    Handle handle_;
};

Generator<int> counted(int limit) {
    for (int i = 0; i < limit; ++i) {
        co_yield i;
    }
}
